import re

def eval_expression(expr):
    """
    Evaluate a mathematical expression string respecting operator precedence.
    Supports +, -, *, /, parentheses, and handles negative numbers.
    Raises ZeroDivisionError when dividing by zero.

    Example: "3 + 4 * (2 - 1)" -> 7
    """

    def tokenize(s):
        tokens = []
        num_str = ''
        for ch in s:
            if ch.isdigit():
                num_str += ch
            elif ch == '-':
                if num_str or len(tokens) > 0 and not (tokens and is_op(tokens[-1])):
                    if num_str:
                        tokens.append(int(num_str))
                        num_str = ''
                    tokens.append('-')
                else:
                    raise ValueError("Invalid placement of '-'")
            elif ch in '+*/()':
                if num_str:
                    tokens.append(int(num_str))
                    num_str = ''
                tokens.append(ch)
            elif ch.isspace():
                continue
            else:
                raise ValueError(f"Unexpected character: {ch}")
        if num_str:
            tokens.append(int(num_str))
        return tokens

    def is_op(token):
        return token in '+-*/()'

    def shunting_yard(tokens):
        output = []
        op_stack = []
        precedence = {'+': 1, '-': 1, '*': 2, '/': 2}
        left_assoc = True

        for token in tokens:
            if isinstance(token, int):
                output.append(token)
            elif token == '(':
                op_stack.append('(')
            elif token == ')':
                while op_stack and op_stack[-1] != '(':
                    output.append(op_stack.pop())
                if not op_stack or op_stack[-1] == '(':
                    raise ValueError("Unmatched parentheses")
                op_stack.pop()
            else:
                while (op_stack and
                       is_op(op_stack[-1]) and
                       left_assoc) or \
                       (not left_assoc and op_stack and
                        is_op(op_stack[-1]) and precedence[op_stack[-1]] > precedence[token]):
                    output.append(op_stack.pop())
                op_stack.append(token)

        while op_stack:
            top = op_stack.pop()
            if top != '(':
                raise ValueError(f"Invalid expression")
            output.append(top)
        return output

    def evaluate_rpn(tokens):
        stack = []
        for token in tokens:
            if isinstance(token, int):
                stack.append(token)
            else:
                if len(stack) < 2:
                    raise ValueError("Invalid expression")
                b = stack.pop()
                a = stack.pop()
                if token == '+':
                    res = a + b
                elif token == '-':
                    res = a - b
                elif token == '*':
                    res = a * b
                elif token == '/':
                    if b == 0:
                        raise ZeroDivisionError("division by zero")
                    # Python division with negative numbers works correctly
                    res = int(a / b)
                else:
                    raise ValueError(f"Invalid operator: {token}")
                stack.append(res)
        if len(stack) != 1:
            raise ValueError("Invalid expression")
        return stack[0]

    # Pre-process the expression to avoid double negatives and ensure consistency
    expr = expr.strip()

    # Validate basic structure with regex
    pattern = re.compile(r'^[\d+\-*/().\s]+$')
    if not pattern.match(expr):
        raise ValueError("Expression contains invalid characters")

    tokens = tokenize(expr)
    rpn = shunting_yard(tokens)
    return evaluate_rpn(rpn)


# Test examples
if __name__ == "__main__":
    print(eval_expression("3 + 4 * (2 - 1)"))       # 7
    print(eval_expression("-3 + 4 * (2 - 1)"))      # 1
    print(eval_expression("10 / (2 - 1)"))          # 10
    print(eval_expression("-5 * 3"))                 # -15
    print(eval_expression("(-2) + (-3) * 4"))       # -14
    try:
        print(eval_expression("1 / 0"))
    except ZeroDivisionError as e:
        print(f"Error: {e}")
